// /frontend-react/src/App.js (FINAL, DEFINITIVE FIX)

import React, { useState } from 'react';
import Dashboard from './components/Dashboard';
import MedicalDashboard from './components/MedicalDashboard';
import AppointmentFlow from './components/AppointmentFlow';
import TransportStatus from './components/TransportStatus';
import MedicineReminder from './components/MedicineReminder';
import SideMenu from './components/SideMenu'; 
import ProfilePage from './components/ProfilePage';
import LanguagePage from './components/LanguagePage';
import EmergencyInfoPage from './components/EmergencyInfoPage'; // Ensure this is imported

// Mock data (remains the same)
const mockAppointmentData = { date: 'Dec 10', time: '10:00 AM', hasTransportBooked: false };

function App() {
    const [currentPage, setCurrentPage] = useState('dashboard'); 
    const [isEasyMode] = useState(true); 
    const [isMenuOpen, setIsMenuOpen] = useState(false); // Controls Modal Visibility

    const handleNotificationClick = () => { setCurrentPage('appointment'); };

    const renderPage = () => {
        
        // --- 1. PRIMARY DASHBOARD ROUTING (Merges all props for Dashboard) ---
        if (currentPage === 'dashboard') {
            return (
                <Dashboard 
                    isEasyMode={isEasyMode} 
                    goToMedical={() => setCurrentPage('medical-dashboard')}
                    // VITAL PROP: Route for Emergency Info icon click
                    goToEmergencyInfo={() => setCurrentPage('emergency-info')} 
                    onMenuClick={() => setIsMenuOpen(true)}
                />
            );
        }

        // --- 2. MEDICAL SUB-DASHBOARD ---
        if (currentPage === 'medical-dashboard') {
            return (<MedicalDashboard isEasyMode={isEasyMode} goToPage={setCurrentPage} onMenuClick={() => setIsMenuOpen(true)} />);
        }
        
        // --- 3. FEATURE PAGES (Appointment, Transport, Medicine) ---
        if (currentPage === 'appointment') {
            return (<AppointmentFlow isEasyMode={isEasyMode} appointment={mockAppointmentData} goToTransportStatus={() => setCurrentPage('transport')} goToMedicalDashboard={() => setCurrentPage('medical-dashboard')} onMenuClick={() => setIsMenuOpen(true)} />);
        }
        if (currentPage === 'transport') {
            return (<TransportStatus isEasyMode={isEasyMode} goToAppointmentFlow={() => setCurrentPage('appointment')} goToMedicalDashboard={() => setCurrentPage('medical-dashboard')} onMenuClick={() => setIsMenuOpen(true)} />);
        }
        if (currentPage === 'medicine') {
            return (<MedicineReminder isEasyMode={isEasyMode} goToPage={setCurrentPage} onMenuClick={() => setIsMenuOpen(true)} />);
        }

        // --- 4. UTILITY PAGES (Profile, Language, Emergency Info) ---
        if (currentPage === 'profile') {
            return (
                <ProfilePage isEasyMode={isEasyMode} goToPage={setCurrentPage} onMenuClick={() => setIsMenuOpen(true)}/>
            );
        }
        if (currentPage === 'language') {
            return (
                <LanguagePage isEasyMode={isEasyMode} goToPage={setCurrentPage} onMenuClick={() => setIsMenuOpen(true)}/>
            );
        }
        if (currentPage === 'emergency-info') {
            return (
                <EmergencyInfoPage 
                    isEasyMode={isEasyMode} 
                    goToPage={setCurrentPage} 
                    onMenuClick={() => setIsMenuOpen(true)} 
                />
            );
        }
        
        return null; // Fallback
    };

    const scrollbarHiddenStyle = {
        'overflowY': 'auto', 'msOverflowStyle': 'none', 'scrollbarWidth': 'none', 
    };

    return (
        <div style={{ /* ... outer styles ... */ }}>
            <div style={{ /* ... phone casing styles ... */ }}>
                {/* Mock Speaker/Notch */}
                <div style={{ /* ... */ }}></div>

                {/* Inner App Content Screen (Scrollable area) */}
                <div 
                    style={{
                        // ... styles ...
                        opacity: isMenuOpen ? 0.3 : 1, 
                        pointerEvents: isMenuOpen ? 'none' : 'auto', 
                        transition: 'opacity 0.3s ease-out',
                    }}
                    className={`App ${isEasyMode ? 'easy-mode-theme' : 'standard-theme'}`}
                >
                    {renderPage()}
                </div>

                {/* --- CENTERED MODAL OVERLAY --- */}
                {isMenuOpen && (
                    <div
                        onClick={() => setIsMenuOpen(false)} 
                        style={{
                            position: 'absolute', top: 0, left: 0, right: 0, bottom: 0,
                            backgroundColor: 'rgba(0, 0, 0, 0.4)',
                            zIndex: 100, 
                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                        }}
                    >
                        <SideMenu
                            isEasyMode={isEasyMode}
                            isOpen={isMenuOpen}
                            onClose={() => setIsMenuOpen(false)}
                            goToPage={setCurrentPage}
                        />
                    </div>
                )}
            </div>
        </div>
    );
}

export default App;
